// fix-health-app-v2.4.12.cjs — Family Health Track v2.4.12 one-step fix
// Run from the project root (the folder with package.json) with:
//   node fix-health-app-v2.4.12.cjs
// Requires v2.4.11 already applied (run the v2.4.9 + v2.4.10 + v2.4.11
// scripts first if you have not run them yet). What it does:
//   1. Backs up each changed file to <file>.bak (first run only)
//   2. Applies the v2.4.12 fix — doctor/admin records now carry the time
//      (not just the date); a just-added record no longer appears twice;
//      Google login removed, login with email OR username + password;
//      height/weight in kg/lb and cm/m/ft-in; main buttons have depth
//   3. Runs npm install, typecheck (tsc), tests (vitest) and build
// Safe to run twice: files already matching the new content are skipped.
// It does NOT touch your data, your Firebase project, or git.
// NOTE: this version DOES change firestore.rules (a new public 'usernames'
// collection for username login) — publish the rules in Firebase Console
// after running the script (see NEXT STEPS). Also disable the Google
// sign-in provider in Firebase Console (Authentication > Sign-in method).
const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const VERSION = '2.4.12';
const FILES = [
  {
    "path": "firestore.rules",
    "b64": ""
  },
  {
    "path": "package.json",
    "b64": ""
  },
  {
    "path": "src/App.tsx",
    "b64": ""
  },
  {
    "path": "src/components/auth/LoginScreen.tsx",
    "b64": ""
  },
  {
    "path": "src/components/layout/Sidebar.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/BMIModule.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/DeleteAccountModal.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/LabTestModule.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/ProfileSetupModal.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/VaccinePassportModule.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/VersionHistoryModal.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/admin/AdminAddPatientModal.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/admin/AdminPatientDetail.tsx",
    "b64": ""
  },
  {
    "path": "src/constants/version.ts",
    "b64": "ZXhwb3J0IGNvbnN0IENVUlJFTlRfU1lTVEVNX1ZFUlNJT04gPSAndjIuNC4xMic7Cg=="
  },
  {
    "path": "src/context/AuthContext.tsx",
    "b64": ""
  },
  {
    "path": "src/context/HealthDataContext.tsx",
    "b64": ""
  },
  {
    "path": "src/index.css",
    "b64": ""
  },
  {
    "path": "src/types/health.ts",
    "b64": ""
  }
];

const norm = (s) => String(s).replace(/\r\n/g, '\n');
let applied = 0, skipped = 0, failed = 0;
const failures = [];
function run(cmd, args, label) {
  console.log('  $ ' + cmd + ' ' + args.join(' '));
  const r = spawnSync(cmd, args, { stdio: 'inherit', shell: process.platform === 'win32' });
  if (r.error || r.status !== 0) {
    console.log('[FAIL] ' + label + ' (exit ' + (r.status ?? r.error) + ')');
    return false;
  }
  console.log('[OK] ' + label);
  return true;
}
function main() {
  console.log('Family Health Track fix — v' + VERSION);
  console.log('Project folder: ' + process.cwd());
  const pkgPath = path.join(process.cwd(), 'package.json');
  if (!fs.existsSync(pkgPath)) {
    console.log('[ERROR] package.json not found here. Run this script from the project root (the folder with package.json).');
    process.exit(1);
  }
  let pkg;
  try { pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8')); } catch (e) {
    console.log('[ERROR] package.json could not be read: ' + e.message);
    process.exit(1);
  }
  if (pkg.name !== 'family-health-track') {
    console.log('[ERROR] This does not look like the Family Health Track project (package name: ' + pkg.name + '). Stopping.');
    process.exit(1);
  }
  if (String(pkg.version) === '2.4.10') {
    console.log('[ERROR] This project is still v2.4.10. Run fix-health-app-v2.4.11.cjs first, then run this script again.');
    process.exit(1);
  }
  if (String(pkg.version) === '2.4.9') {
    console.log('[ERROR] This project is still v2.4.9. Run fix-health-app-v2.4.10.cjs, then fix-health-app-v2.4.11.cjs, then run this script again.');
    process.exit(1);
  }
  if (String(pkg.version) === '2.4.8' || String(pkg.version) === '2.4.7' || String(pkg.version) === '2.4.6') {
    console.log('[ERROR] This project is still v' + pkg.version + '. Run the v2.4.9, v2.4.10 and v2.4.11 scripts first (in order), then run this script again.');
    process.exit(1);
  }
  if (!['2.4.11', '2.4.12'].includes(String(pkg.version))) {
    console.log('[ERROR] Unexpected project version ' + pkg.version + ' (expected 2.4.11). Stopping — ask for help before running this.');
    process.exit(1);
  }
  for (const f of FILES) {
    const dest = path.join(process.cwd(), ...f.path.split('/'));
    const next = Buffer.from(f.b64, 'base64').toString('utf8');
    try {
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      if (fs.existsSync(dest) && norm(fs.readFileSync(dest, 'utf8')) === norm(next)) {
        console.log('[SKIP] already applied: ' + f.path);
        skipped++;
        continue;
      }
      if (fs.existsSync(dest) && !fs.existsSync(dest + '.bak')) {
        fs.copyFileSync(dest, dest + '.bak');
      }
      fs.writeFileSync(dest, next, 'utf8');
      console.log('[OK] applied: ' + f.path);
      applied++;
    } catch (e) {
      console.log('[FAIL] ' + f.path + ': ' + e.message);
      failed++;
      failures.push(f.path + ': ' + e.message);
    }
  }
  console.log('');
  console.log('Applied ' + applied + ' | Already applied ' + skipped + ' | Failed ' + failed);
  if (failed > 0) {
    console.log('Failures: ' + failures.join(' ; '));
    console.log('Stopping before checks. Your .bak backups are next to the originals.');
    process.exit(1);
  }
  console.log('');
  console.log('--- checks (npm install, typecheck, tests, build) ---');
  const okInstall = run('npm', ['install', '--no-audit', '--no-fund'], 'npm install');
  const okLint = run('npx', ['tsc', '--noEmit'], 'typecheck (tsc --noEmit)');
  const okTest = run('npx', ['vitest', 'run'], 'tests (vitest run)');
  const okBuild = run('npm', ['run', 'build'], 'build (vite build)');
  if (!okInstall || !okLint || !okTest || !okBuild) {
    console.log('');
    console.log('[DONE WITH ERRORS] Files were updated, but a check failed above.');
    console.log('Do NOT deploy yet. Ask for help and include the error lines above.');
    process.exit(1);
  }
  console.log('');
  console.log('[DONE] v' + VERSION + ' applied. Applied ' + applied + ' | Already applied ' + skipped + ' | Failed 0');
  console.log('');
  console.log('NEXT STEPS (do these in order):');
  console.log('  1. Firebase Console > Firestore Database > Rules: publish the new');
  console.log('     firestore.rules (this version adds the public usernames');
  console.log('     collection — username login cannot work without it).');
  console.log('  2. Firebase Console > Authentication > Sign-in method: DISABLE');
  console.log('     the Google provider (the app no longer offers Google login).');
  console.log('  3. Deploy / push the app (git push, then Cloudflare redeploys).');
  console.log('  4. On your device, hard-refresh once (Ctrl+Shift+R).');
  console.log('     Version History must show v2.4.12.');
  console.log('  5. Try: as admin, add a BP record for a patient — the list must');
  console.log('     show date + time, and the record must appear only ONCE');
  console.log('     (no duplicate before refresh). Create a new account with a');
  console.log('     username, log out, and log back in with the username.');
  console.log('     Note: accounts previously made with Google must set a');
  console.log('     password via "forgot password" first, then log in by email.');
}
main();
